import csv, json, math, collections
import numpy as np

G = 2.955
N = 2000
KN = ['lr','batch','sched','init_scale','precision']

def key(r):
    return (float(r['lr']), int(r['batch']), r['sched'], float(r['init_scale']), r['precision'])

def load():
    man = collections.Counter()
    for r in csv.DictReader(open('/app/manifest.csv')):
        man[key(r)] += 1
    res = collections.defaultdict(list)
    for r in csv.DictReader(open('/app/results.csv')):
        res[key(r)].append(float(r['val_loss']))
    return man, res

def Phi(z):
    return 0.5*(1+math.erf(z/math.sqrt(2)))

def cell_ll(mu, sig, p, n, sx, sxx, Nl):
    z = (G-mu)/sig
    pm = p + (1-p)*(1-Phi(z))
    if pm <= 0: pm = 1e-300
    ll = (Nl-n)*math.log(pm)
    if n:
        ll += n*math.log(1-p) - n*math.log(sig) - 0.5*(sxx - 2*mu*sx + n*mu*mu)/sig**2 - 0.5*n*math.log(2*math.pi)
    return ll

def golden(f, a, b, tol=1e-7):
    gr = (math.sqrt(5)-1)/2
    c = b - gr*(b-a); d = a + gr*(b-a)
    fc, fd = f(c), f(d)
    while abs(b-a) > tol:
        if fc > fd:
            b, d, fd = d, c, fc
            c = b - gr*(b-a); fc = f(c)
        else:
            a, c, fc = c, d, fd
            d = a + gr*(b-a); fd = f(d)
    return (a+b)/2

def fit(man, res, iters=30):
    cells = [k for k in man if len(res.get(k, [])) > 0]
    stats = {}
    for k in cells:
        x = np.array(res[k]); stats[k] = (len(x), x.sum(), (x*x).sum(), man[k])
    batches = sorted({k[1] for k in man})
    sig = 0.09
    p = {b: 0.1 for b in batches}
    mu = {k: min(stats[k][1]/stats[k][0], G) for k in cells}
    for it in range(iters):
        for k in cells:
            n, sx, sxx, Nl = stats[k]
            mu[k] = golden(lambda m: cell_ll(m, sig, p[k[1]], n, sx, sxx, Nl), 2.0, 4.0)
        def tot(sig_, p_):
            return sum(cell_ll(mu[k], sig_, p_[k[1]], *stats[k]) for k in cells)
        sig = golden(lambda s: tot(s, p), 0.03, 0.2)
        for b in batches:
            def f(pb):
                pp = dict(p); pp[b] = pb
                return sum(cell_ll(mu[k], sig, pb, *stats[k]) for k in cells if k[1] == b)
            p[b] = golden(f, 1e-6, 0.9)
    return mu, sig, p

if __name__ == '__main__':
    man, res = load()
    mu, sig, p = fit(man, res)
    print('sigma', sig, 'p', p)
    for k in sorted(mu):
        n = len(res[k]); print(k, n, round(np.mean(res[k]),4), round(mu[k],4), 'guardfrac', round((1-p[k[1]])*(1-Phi((G-mu[k])/sig)),4))
