import json, math, collections, numpy as np
from fit import load, fit, Phi, G, N, KN

man, res = load()
mu, sig, p = fit(man, res)
queries = json.load(open('/app/queries.json'))
cells = json.load(open('/app/report_cells.json'))
levels = json.load(open('/app/sweep.json'))['levels']
launched_levels = {kn: {k[i] for k in man} for i, kn in enumerate(KN)}

def ck(d):
    return (float(d['lr']), int(d['batch']), d['sched'], float(d['init_scale']), d['precision'])

def answer(mu, sig, p):
    out = {}
    for q in queries:
        a = dict(q['baseline']); a[q['knob']] = q['from']
        b = dict(q['baseline']); b[q['knob']] = q['to']
        ka, kb = ck(a), ck(b)
        reason = None
        for k in (ka, kb):
            for i, kn in enumerate(KN):
                if k[i] not in launched_levels[kn]:
                    reason = 'level_never_launched'
        if reason is None and (ka not in man or kb not in man):
            reason = 'combination_never_launched'
        if reason is None and (ka not in mu or kb not in mu):
            reason = 'no_surviving_run'
        if reason:
            out[q['id']] = {'verdict': 'underdetermined', 'reason': reason}
        else:
            out[q['id']] = {'verdict': 'identified', 'delta': mu[kb] - mu[ka]}
    cens = {}
    for c in cells:
        k = ck(c['cell'])
        if k in mu:
            cens[c['id']] = (1-p[k[1]])*(1-Phi((G-mu[k])/sig))
        else:
            cens[c['id']] = 1-p[k[1]]  # all non-preempted runs removed by guard
    return out, cens

out, cens = answer(mu, sig, p)
for q in queries: print(q['id'], q['tol'], out[q['id']])
for c in cells: print(c['id'], c['tol'], round(cens[c['id']],4))
json.dump({'queries': out, 'censoring': cens}, open('/app/answers.json','w'), indent=1)

# parametric bootstrap: simulate pipeline from fitted params, refit, compare
rng = np.random.default_rng(0)
truth_out, truth_cens = out, cens
errs = collections.defaultdict(list)
B = 40
for b in range(B):
    sres = collections.defaultdict(list)
    for k in man:
        m = mu.get(k, 3.3)
        x = rng.normal(m, sig, N)
        keep = (rng.random(N) >= p[k[1]]) & (x <= G)
        if keep.any(): sres[k] = list(x[keep])
    smu, ssig, sp = fit(man, sres, iters=15)
    so, sc = answer(smu, ssig, sp)
    for q in queries:
        i = q['id']
        if 'delta' in so[i]: errs[i].append(so[i]['delta'] - truth_out[i]['delta'])
    for c in cells:
        errs[c['id']].append(sc[c['id']] - truth_cens[c['id']])
tols = {q['id']: q['tol'] for q in queries}; tols.update({c['id']: c['tol'] for c in cells})
for i, e in errs.items():
    e = np.array(e); print(i, 'bias %.4f sd %.4f  tol %.3f  tol/sd %.1f' % (e.mean(), e.std(), tols[i], tols[i]/e.std()))
